-- Fällige Talents-Warnungen (Stefan 18.10.2026, Vertrag Migration 42): abgelaufen, ablauf_bald, einbruch;
-- nur noch nicht gemeldete Ereignisse mit Empfängern (persönliche Schalter talents_verbindung / talents_einbruch).
SELECT talents_warnungen() AS r;

parameters.jsCode:
// Talents-Warnungen (Stefan 18.10.2026): eine Chat-Nachricht je Warnung und Empfänger; Texte und Empfänger aus talents_warnungen().
// Chat-Layout (Vorgabe Stefan): Titel fett mit Doppelpunkt, Inhalt direkt darunter, keine Emojis.
// Testläufe (alles außer production) senden nichts und merken nichts.
// Migration 46 (Stefan 18.10.2026): Warnungen ohne Kanal (kanal_id null: kampagne_fehlt, loeschfrist) werden zugestellt; sie gehören zu einem Talent
// (talent_id) und werden je Talent und Ereignis gemerkt. kanal_id (Zahl oder null) und talent_id gehen weiter an "Gesendet auswerten".
const test = $execution.mode !== 'production';
const r = $input.first().json.r || {};
if (r.ok !== true) throw new Error('Talents-Warnungen: ' + String(r.fehler || 'Die Warnungen sind nicht lesbar.').slice(0, 200));
const ohneEmoji = v => String(v ?? '').replace(/[\p{Extended_Pictographic}\u{FE0F}\u{200D}]/gu, '').trim();
const esc = v => ohneEmoji(v).split('&').join('&amp;').split('<').join('&lt;').split('>').join('&gt;');
const out = [];
for (const w of Array.isArray(r.warnungen) ? r.warnungen : []) {
  const mitKanal = w && w.kanal_id !== null && w.kanal_id !== undefined;
  const kanalId = mitKanal ? Number(w.kanal_id) : null;
  const talentId = Number(w && w.talent_id) > 0 ? Number(w.talent_id) : null;
  const ereignis = String((w && w.ereignis) || '');
  if ((mitKanal ? !(kanalId > 0) : !talentId) || !/^[a-z_]{1,30}:[0-9A-Za-z]{1,40}$/.test(ereignis)) continue;
  const titel = ohneEmoji(w.titel).replace(/:\s*$/, '') + ':';
  const text = ohneEmoji(w.text);
  if (!text) continue;
  for (const e of Array.isArray(w.empfaenger) ? w.empfaenger : []) {
    const roomId = String((e && e.room_id) || '').trim();
    const userId = String((e && e.user_id) || '').trim();
    if (!roomId && !userId) continue;
    out.push({ json: { kanal_id: kanalId, talent_id: talentId, ereignis, art: String(w.art || ''), user_id: userId, room_id: roomId,
      text: titel + '\n' + text, html: '<strong>' + esc(titel) + '</strong><br>' + esc(text), test } });
  }
}
return out;

// Testlauf: zeigt, was gesendet würde; es wird nichts gesendet und nichts gemerkt
return $input.all().map(i => ({ json: { vorschau: 'würde senden (Testlauf, nichts gesendet, nichts gemerkt)', an: i.json.user_id, room_id: i.json.room_id,
  kanal_id: i.json.kanal_id, ereignis: i.json.ereignis, text: i.json.text, html: i.json.html } }));

// Gesendet auswerten (Stefan 18.10.2026): eine Warnung gilt als gemeldet, wenn sie mindestens einem Empfänger zugestellt wurde
// (erst nach dem Senden merken). Gelingt das Senden an niemanden, bleibt sie offen und wird beim nächsten Lauf erneut versucht.
const gesendet = $input.all();
const quelle = $('Testlauf?').all(1);
const gruppen = {};
gesendet.forEach((it, i) => {
  let q = quelle[i];
  if (quelle.length !== gesendet.length) {
    const p = Array.isArray(it.pairedItem) ? it.pairedItem[0] : it.pairedItem;
    q = p && typeof p.item === 'number' ? quelle[p.item] : undefined;
  }
  if (!q || !q.json) return;
  const j = it.json || {};
  const ok = !j.error && j.ok !== false;
  // Migration 46 (Stefan 18.10.2026): Warnungen ohne Kanal gruppiert je Talent (t<talent_id>)
  const key = (q.json.kanal_id ?? ('t' + q.json.talent_id)) + '|' + q.json.ereignis;
  const g = gruppen[key] = gruppen[key] || { kanal_id: q.json.kanal_id ?? null, talent_id: q.json.talent_id ?? null, ereignis: q.json.ereignis, art: q.json.art, gesendet: 0, fehlgeschlagen: 0, test: q.json.test };
  if (ok) g.gesendet++; else g.fehlgeschlagen++;
});
return Object.keys(gruppen).map(k => gruppen[k]).filter(g => g.gesendet > 0 && g.test === false).map(g => ({ json: g }));

parameters.query:
-- Warnung als gemeldet merken (Stefan 18.10.2026), erst nach dem Senden; einmal je Kanal und Ereignis.
-- Migration 46 (Stefan 18.10.2026): ohne Kanal ($1 leer) je Talent (talents_warnung_gemeldet liest das Talent aus dem Ereignis).
SELECT nullif($1::text, '')::integer AS kanal_id, $2::text AS ereignis, talents_warnung_gemeldet(nullif($1::text, '')::integer, $2::text) AS r;

