// Löschmeldungen bauen (Stefan 18.10.2026, Migration 46): je Meldung aus talents_loeschfrist_ausfuehren() und Empfänger eine Chat-Nachricht
// (gleiches Layout wie die Warnungen: Titel fett mit Doppelpunkt, keine Emojis). Werden nicht gemerkt (das Talent ist gelöscht).
// Fehler der Tagesaufgaben brechen den Ablauf ab (Meldung über SYS 7); nur echte Läufe kommen hierher.
const l = ($input.first().json || {}).l || {};
if (l.ok !== true) throw new Error('Talents-Löschfrist: ' + String(l.fehler || 'Das Ergebnis ist nicht lesbar.').slice(0, 200));
const ohneEmoji = v => String(v ?? '').replace(/[\p{Extended_Pictographic}\u{FE0F}\u{200D}]/gu, '').trim();
const esc = v => ohneEmoji(v).split('&').join('&amp;').split('<').join('&lt;').split('>').join('&gt;');
const out = [];
for (const m of Array.isArray(l.meldungen) ? l.meldungen : []) {
  const titel = ohneEmoji(m && m.titel).replace(/:\s*$/, '') + ':';
  const text = ohneEmoji(m && m.text);
  if (!text) continue;
  for (const e of Array.isArray(m.empfaenger) ? m.empfaenger : []) {
    const roomId = String((e && e.room_id) || '').trim(), userId = String((e && e.user_id) || '').trim();
    if (!roomId && !userId) continue;
    out.push({ json: { talent_id: m.talent_id ?? null, user_id: userId, room_id: roomId, text: titel + '\n' + text, html: '<strong>' + esc(titel) + '</strong><br>' + esc(text) } });
  }
}
return out;

