-- Dateien gelöschter Talents (Stefan 18.10.2026, Vertrag Migration 51 §6.1): offene Einträge (erst Dateien, dann Ordner) und die Admins
-- für den Hinweis auf aufgegebene Dateien. Nur im echten täglichen Lauf nach den Tagesaufgaben (löscht endgültig).
SELECT talents_loesch_dateien_liste(20) AS r, talents_admin_empfaenger() AS admins;

parameters.jsCode:
// Dateien gelöschter Talents im Speicherort entfernen (Stefan 18.10.2026, Vertrag Migration 51 §6.1). Nur im echten täglichen Lauf (nach den
// Tagesaufgaben): Speicherort von Ally über SPEICHER 1 "loeschen", Cloud-Speicherorte über TALENTS Ablage "loeschen" (Vertrag 51 §6.4; Antwort
// {ok, fehlt, fehler}; scheitert das Löschen, wird der Eintrag nach 5 Versuchen aufgegeben). Ist "hinweis" gesetzt (aufgegebene Dateien der
// letzten 7 Tage), geht er an die Admins. Fehlt die Liste (z. B. Migration 51 noch nicht eingespielt), passiert hier nichts.
const x = $input.first().json || {};
const r = x.r || {};
if (r.ok !== true) return [];
const out = [];
for (const d of Array.isArray(r.dateien) ? r.dateien : []) {
  const id = Number(d && d.id);
  if (!(id > 0)) continue;
  const pfad = String(d.pfad || ''), dienst = String(d.dienst || '');
  if (dienst === 'ally') { if (pfad) out.push({ json: { weg: 'ally', id, aktion: 'loeschen', bereich: 'ally', pfad } }); }
  else if (dienst) out.push({ json: { weg: 'cloud', id, aktion: 'loeschen', datei: { dienst, extern_id: d.extern_id ?? null, pfad } } });
}
const ohneEmoji = v => String(v ?? '').replace(/[\p{Extended_Pictographic}\u{FE0F}\u{200D}]/gu, '').trim();
const esc = v => ohneEmoji(v).split('&').join('&amp;').split('<').join('&lt;').split('>').join('&gt;');
const hinweis = ohneEmoji(r.hinweis);
if (hinweis) {
  const titel = 'Talents: Dateien nicht gelöscht:';
  for (const e of Array.isArray(x.admins) ? x.admins : []) {
    const roomId = String((e && e.room_id) || '').trim(), userId = String((e && e.user_id) || '').trim();
    if (!roomId && !userId) continue;
    out.push({ json: { weg: 'hinweis', user_id: userId, room_id: roomId, text: titel + '\n' + hinweis, html: '<strong>' + esc(titel) + '</strong><br>' + esc(hinweis) } });
  }
}
return out;

// Ergebnis je Datei für talents_loesch_datei_ergebnis (Stefan 18.10.2026, Vertrag Migration 51 §6.1): gelöscht {ok:true}, gab es nicht {fehlt:true},
// sonst {ok:false, fehler}. SPEICHER 1 meldet ok mit vorhanden true/false; TALENTS Ablage {ok, fehlt, fehler}.
const passend = (k, i) => { try { return $(k).itemMatching(i); } catch (e) { return $(k).all()[i]; } };
const out = [];
$input.all().forEach((it, i) => {
  const a = passend('Löschaufträge', i);
  const id = Number(a && a.json && a.json.id);
  if (!(id > 0)) return;
  const j = it.json || {};
  let daten;
  if (j.ok === true && (j.vorhanden === false || j.fehlt === true)) daten = { fehlt: true };
  else if (j.ok === true) daten = { ok: true };
  else daten = { ok: false, fehler: String(j.fehler || (j.error && (j.error.message || j.error)) || 'Unbekannter Fehler.').slice(0, 300) };
  out.push({ json: { id, daten: JSON.stringify(daten) } });
});
return out;
